from pathlib import Path
import sys, base64, json

root=Path(sys.argv[1])
public=root/'public'
app=public/'app.js'
cssp=public/'styles.css'
indexp=public/'index.html'
manifestp=public/'manifest.webmanifest'
swp=public/'sw.js'

LOGO_B64=''
ICON512_B64=''
ICON192_B64=''
ICON192_B64=''

(public/'ritmo-logo.png').write_bytes(base64.b64decode(LOGO_B64))
(public/'ritmo-icon-512.png').write_bytes(base64.b64decode(ICON512_B64))
(public/'ritmo-icon-192.png').write_bytes(base64.b64decode(ICON192_B64))

s=app.read_text()
old_brand='const brand=()=>`<div class="brand"><div class="brand-mark"><span class="brand-dot"></span><svg viewBox="0 0 48 48" fill="none"><path d="M12 38V16c0-5 4-9 9-9h7c6 0 10 4 10 9 0 6-4 9-10 9h-8" stroke="white" stroke-width="4" stroke-linecap="round"/><path d="m25 25 12 13" stroke="white" stroke-width="4" stroke-linecap="round"/></svg></div><div class="brand-copy"><strong>Ritmo</strong><small>gestão financeira pessoal</small></div></div>`;'
new_brand='const brand=()=>`<div class="brand"><img class="brand-logo-full" src="/ritmo-logo.png" alt="Ritmo"><img class="brand-icon-only" src="/ritmo-icon-192.png" alt="" aria-hidden="true"></div>`;'
if old_brand not in s: raise SystemExit('Marca antiga não encontrada')
s=s.replace(old_brand,new_brand,1)

old_mobile='<div class="brand"><div class="brand-mark"><span class="brand-dot"></span><svg viewBox="0 0 48 48" fill="none"><path d="M12 38V16c0-5 4-9 9-9h7c6 0 10 4 10 9 0 6-4 9-10 9h-8" stroke="white" stroke-width="4" stroke-linecap="round"/><path d="m25 25 12 13" stroke="white" stroke-width="4" stroke-linecap="round"/></svg></div></div>'
new_mobile='<div class="brand brand-mobile"><img class="brand-icon-mobile" src="/ritmo-icon-192.png" alt="Ritmo"></div>'
if old_mobile not in s: raise SystemExit('Marca mobile antiga não encontrada')
s=s.replace(old_mobile,new_mobile,1)

s=s.replace("['more','Mais','menu']","['more','Menu','menu']",1)
s=s.replace('Início e Mais ficam fixos.','Início e Menu ficam fixos.')

# Menu: Atualizar Sistema no topo, com destaque dourado, e não dentro de Aplicativo.
a=s.find('function morePage(){')
b=s.find('\nfunction shortcutsPage(',a)
if a<0 or b<0: raise SystemExit('morePage não encontrada')
update_icon='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6v5h-5"/><path d="M4 18v-5h5"/><path d="M18.4 9A7 7 0 0 0 6.2 6.2L4 8"/><path d="M5.6 15A7 7 0 0 0 17.8 17.8L20 16"/></svg>'
more="""function morePage(){const update=`<button type=\"button\" class=\"system-update-btn menu-update-btn\" data-system-update aria-label=\"Atualizar Sistema\" title=\"Atualizar Sistema\">"""+update_icon+"""</button>`;return `${head('Menu','Acesse ferramentas, conta e informações do Ritmo.',update)}<div class=\"more-sections\"><section class=\"more-section\"><h3>Ferramentas</h3><div class=\"more-grid\"><button class=\"more-card\" data-page=\"calendar\"><span class=\"more-icon calendar-tone\">${ic('calendar',22)}</span><div><strong>Calendário</strong><small>Movimentações e vencimentos por dia.</small></div>${ic('chev',16)}</button><button class=\"more-card\" data-page=\"insights\"><span class=\"more-icon insight-tone\">${ic('spark',22)}</span><div><strong>Insights</strong><small>Entenda melhor seus dados financeiros.</small></div>${ic('chev',16)}</button><button class=\"more-card\" data-page=\"shortcuts\"><span class=\"more-icon shortcut-tone\">${ic('menu',22)}</span><div><strong>Personalizar atalhos</strong><small>Escolha e ordene os atalhos da barra inferior.</small></div>${ic('chev',16)}</button></div></section><section class=\"more-section\"><h3>Sua conta</h3><div class=\"more-grid\"><button class=\"more-card\" data-page=\"profile\"><span class=\"more-icon\">${ic('user',22)}</span><div><strong>Editar perfil</strong><small>Nome, usuário e senha.</small></div>${ic('chev',16)}</button></div></section><section class=\"more-section\"><h3>Aplicativo</h3><div class=\"more-grid\"><button class=\"more-card\" data-page=\"settings\"><span class=\"more-icon settings-tone\">${ic('gear',22)}</span><div><strong>Configurações</strong><small>Aparência, notificações e segurança.</small></div>${ic('chev',16)}</button><button class=\"more-card\" data-settings-open=\"about\"><span class=\"more-icon info-tone\">${ic('info',22)}</span><div><strong>Sobre o Ritmo</strong><small>Versão e informações do aplicativo.</small></div>${ic('chev',16)}</button><a class=\"more-card\" href=\"https://wa.me/5574998029574?text=Ol%C3%A1%20Fl%C3%A1vio%2C%20eu%20gostaria%20de%20suporte%20no%20Ritmo.\" target=\"_blank\" rel=\"noopener\"><span class=\"more-icon support-tone\">${ic('message',22)}</span><div><strong>Suporte Rocha Tech</strong><small>Fale diretamente pelo WhatsApp.</small></div>${ic('chev',16)}</a></div></section></div>`}"""
s=s[:a]+more+s[b:]
app.write_text(s)

css=cssp.read_text()
css += r'''

/* Identidade oficial Ritmo */
.brand{display:flex;align-items:center;gap:0}.brand-logo-full{display:block;width:158px;max-width:100%;height:auto;object-fit:contain}.brand-icon-only{display:none;width:42px;height:42px;object-fit:contain}.brand-mobile{display:flex;align-items:center}.brand-icon-mobile{width:42px;height:42px;object-fit:contain;display:block}.side-top .brand-logo-full{width:152px}.auth-card .brand{justify-content:center}.auth-card .brand-logo-full{width:196px}.auth-hero>.brand{width:max-content;background:rgba(255,255,255,.94);padding:9px 13px;border-radius:16px;box-shadow:0 8px 22px rgba(0,0,0,.08)}.auth-hero>.brand .brand-logo-full{width:170px}.about-logo .brand-logo-full{width:190px}.lock-card .brand{justify-content:center}.lock-card .brand-logo-full{width:190px}.app.collapsed .brand-logo-full{display:none}.app.collapsed .brand-icon-only{display:block}.app.collapsed .side-top .brand{justify-content:center}.menu-update-btn{background:color-mix(in srgb,var(--gold) 23%,var(--surface-solid));color:#a86d24;border-color:color-mix(in srgb,var(--gold) 58%,var(--line));box-shadow:0 7px 18px color-mix(in srgb,var(--gold) 18%,transparent)}.menu-update-btn:hover{background:color-mix(in srgb,var(--gold) 32%,var(--surface-solid));color:#8b571b}html.dark .menu-update-btn{color:#f0bf82}.page-head .menu-update-btn{flex:0 0 auto}
@media(max-width:760px){.brand-icon-mobile{width:44px;height:44px}.page-head .menu-update-btn{width:42px;height:42px;border-radius:13px}.auth-card .brand-logo-full{width:205px}}
'''
cssp.write_text(css)

idx=indexp.read_text().replace('/icon.svg','/ritmo-icon-192.png')
indexp.write_text(idx)
manifest={
  'name':'Ritmo','short_name':'Ritmo','description':'Gestão financeira pessoal','start_url':'/','scope':'/','display':'standalone',
  'background_color':'#F7F5EF','theme_color':'#0F4C5C',
  'icons':[
    {'src':'/ritmo-icon-192.png','sizes':'192x192','type':'image/png','purpose':'any'},
    {'src':'/ritmo-icon-512.png','sizes':'512x512','type':'image/png','purpose':'any maskable'}
  ]
}
manifestp.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
sw=swp.read_text()
sw=sw.replace("'/icon.svg'","'/ritmo-logo.png','/ritmo-icon-192.png','/ritmo-icon-512.png'")
swp.write_text(sw)
print('Ritmo V1: marca oficial aplicada, Mais renomeado para Menu e Atualizar Sistema movido para o topo em dourado.')
